const pickTestRestoreRun = `-- name: PickTestRestoreRun :one
SELECT r.id FROM runs r
WHERE r.job_id = $1 AND r.status = 'success'
  AND EXISTS (
      SELECT 1 FROM run_items ri JOIN artifacts a ON a.run_item_id = ri.id
      WHERE ri.run_id = r.id AND ri.kind = 'database' AND ri.status = 'success' AND ri.verified
        AND a.state = 'present' AND a.verified AND a.signing_key_id IS NOT NULL
  )
ORDER BY r.storage_timestamp DESC NULLS LAST, r.queued_at DESC, r.id DESC
LIMIT 1
`

// PickTestRestoreRun is the newest successful run of a job with at least
// one present, verified, signed database artifact.
func (q *Queries) PickTestRestoreRun(ctx context.Context, jobID uuid.UUID) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, pickTestRestoreRun, jobID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const setJobTestRestore = `-- name: SetJobTestRestore :one

UPDATE jobs
SET test_restore_enabled = $1,
    test_restore_schedule = $2,
    test_restore_connection_id = $3::uuid,
    test_restore_next_at = $4::timestamptz,
    test_restore_target_privileges = $5::text,
    test_restore_privilege_reasons = $6::text[],
    test_restore_privileged_ack_by = $7::uuid,
    test_restore_privileged_ack_at = $8::timestamptz,
    updated_by = $9
WHERE id = $10 AND deleted_at IS NULL
RETURNING id, enabled, schedule, next_run_at, last_scheduled_at, deleted_at, created_at, updated_at, name, slug, description, connection_id, db_mode, databases, exclude, include_globals, retention_keep_last, retention_keep_days, timeout_seconds, verification, expected_window_seconds, created_by, updated_by, test_restore_enabled, test_restore_schedule, test_restore_connection_id, test_restore_next_at, test_restore_target_privileges, test_restore_privilege_reasons, test_restore_privileged_ack_by, test_restore_privileged_ack_at
`

type SetJobTestRestoreParams struct {
	Enabled          bool            `json:"enabled"`
	Schedule         json.RawMessage `json:"schedule"`
	ConnectionID     *uuid.UUID      `json:"connectionId"`
	NextAt           *time.Time      `json:"nextAt"`
	TargetPrivileges *string         `json:"targetPrivileges"`
	PrivilegeReasons []string        `json:"privilegeReasons"`
	PrivilegedAckBy  *uuid.UUID      `json:"privilegedAckBy"`
	PrivilegedAckAt  *time.Time      `json:"privilegedAckAt"`
	UpdatedBy        *uuid.UUID      `json:"updatedBy"`
	ID               uuid.UUID       `json:"id"`
}

// Scheduled test restores (task 4.6). The settings live on jobs and are
// written only by internal/jobs; test_restores / test_restore_items only by
// internal/restore.
// SetJobTestRestore changes a job's test-restore settings.
func (q *Queries) SetJobTestRestore(ctx context.Context, arg SetJobTestRestoreParams) (Job, error) {
	row := q.db.QueryRow(ctx, setJobTestRestore,
		arg.Enabled,
		arg.Schedule,
		arg.ConnectionID,
		arg.NextAt,
		arg.TargetPrivileges,
		arg.PrivilegeReasons,
		arg.PrivilegedAckBy,
		arg.PrivilegedAckAt,
		arg.UpdatedBy,
		arg.ID,
	)
	var i Job
	err := row.Scan(
		&i.ID,
		&i.Enabled,
		&i.Schedule,
		&i.NextRunAt,
		&i.LastScheduledAt,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Name,
		&i.Slug,
		&i.Description,
		&i.ConnectionID,
		&i.DbMode,
		&i.Databases,
		&i.Exclude,
		&i.IncludeGlobals,
		&i.RetentionKeepLast,
		&i.RetentionKeepDays,
		&i.TimeoutSeconds,
		&i.Verification,
		&i.ExpectedWindowSeconds,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.TestRestoreEnabled,
		&i.TestRestoreSchedule,
		&i.TestRestoreConnectionID,
		&i.TestRestoreNextAt,
		&i.TestRestoreTargetPrivileges,
		&i.TestRestorePrivilegeReasons,
		&i.TestRestorePrivilegedAckBy,
		&i.TestRestorePrivilegedAckAt,
	)
	return i, err
}

